def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_prime_pairs_sum_800():
    pairs = []
    # We only check up to 400 since p < r (p + r = 800)
    for n in range(2, 400):
        if is_prime(n):
            m = 800 - n
            if is_prime(m) and m > n:
                pairs.append((n, m))
    return pairs

pairs_800 = find_prime_pairs_sum_800()
print("Prime pairs (X, Y) such that X + Y = 800 and X < Y:")
for p_val, r_val in pairs_800:
    print(f"p={p_val}, r={r_val}")

